#!/usr/bin/env python3
"""Strict post-run gate for the guarded R3 discrete roll-LQR pilot."""
import argparse,csv,json,math,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT));sys.path.insert(0,str(ROOT/'scripts'))
from lqr.discrete_cascade_roll_lqr import COMMAND_LIMIT,SLEW_LIMIT,DiscreteCascadeRollLQR
from run_rich_r3_roll_dualrate_xp12 import start_reasons

def main():
 p=argparse.ArgumentParser();p.add_argument('csv',type=Path);p.add_argument('--require-engaged',action='store_true');a=p.parse_args()
 with a.csv.open(newline='') as f:rows=list(csv.DictReader(f))
 if not rows:raise SystemExit('empty log')
 t=np.array([float(r['t_s']) for r in rows]);dt=np.diff(t);updates=np.array([int(r['fallback_update']) for r in rows],bool);fb=np.array([float(r['fallback_roll_command']) for r in rows]);held=np.ones(len(rows),bool);held[1:]=updates[1:]|np.isclose(fb[1:],fb[:-1],atol=1e-15);runtime=DiscreteCascadeRollLQR();expected=[runtime.update(float(r['p_error_deg_s']),float(r['total_roll_perturbation']),float(r['yoke_roll_perturbation'])) for r in rows];command=np.array([float(r['lqr_command_perturbation']) for r in rows]);raw=np.array([float(r['lqr_raw_command']) for r in rows]);error=max(max(abs(command[i]-expected[i]['command']),abs(raw[i]-expected[i]['raw_command'])) for i in range(len(rows)));latched=np.array([int(r['fallback_latched']) for r in rows],bool);selection=np.array([float(r['selected_roll_command']) for r in rows]);expected_selection=np.where(latched,fb,np.array([float(r['lqr_roll_command']) for r in rows]));first={k:float(rows[0][k]) for k in ('altitude_m','ias_kts','pitch_deg','roll_deg','p_deg_s','q_deg_s','r_deg_s','art_stab_on','override_roll','override_pitch','paused','sim_speed','replay')};reasons=start_reasons(first);engaged=all(r['engaged']=='1' and r['controls_sent']=='1' for r in rows)
 checks={'completeness':len(rows)>=1040,'maximum_gap':len(dt)>0 and float(dt.max())<=.071428572,'mean_rate':len(dt)>0 and 34<=1/float(dt.mean())<=36,'fallback_update_count':297<=int(updates.sum())<=303,'fallback_held':np.all(held),'zero_initial_state':all(abs(float(rows[0][k]))<=1e-15 for k in ('p_error_deg_s','total_roll_perturbation','yoke_roll_perturbation','lqr_command_perturbation')),'exact_runtime_replay':error<=1e-15,'command_bound':np.max(np.abs(command))<=COMMAND_LIMIT+1e-15,'slew_bound':np.max(np.abs(np.diff(command)))<=SLEW_LIMIT+1e-15,'permanent_latch':np.all(np.diff(latched.astype(int))>=0),'selection_exact':np.max(np.abs(selection-expected_selection))<=1e-15,'no_fallback_latch':not latched[-1],'start_gate':not reasons,'engagement':engaged if a.require_engaged else not engaged,'ownership_started_clear':first['override_roll']==0 and first['override_pitch']==0,'ownership_restored':all(r['restored_roll_override']=='0' and r['restored_pitch_override']=='0' and abs(float(r['restored_roll_yoke_error']))<=1e-6 and abs(float(r['restored_pitch_yoke_error']))<=1e-6 for r in rows),'live_state':all(float(r['paused'])==0 and float(r['sim_speed'])==1 and float(r['replay'])==0 for r in rows),'safety':all(abs(float(r['pitch_deg']))<=10 and abs(float(r['roll_deg']))<=10 and max(abs(float(r[k])) for k in ('p_deg_s','q_deg_s','r_deg_s'))<=20 for r in rows),'finite':all(math.isfinite(float(v)) for r in rows for k,v in r.items() if k!='fallback_reason')};checks={k:bool(v) for k,v in checks.items()};result={'file':str(a.csv),'rows':len(rows),'effective_hz':1/float(dt.mean()),'max_gap_s':float(dt.max()),'fallback_updates':int(updates.sum()),'engaged':engaged,'fallback_latched':bool(latched[-1]),'fallback_reason':rows[-1]['fallback_reason'],'peak_abs_lqr_command':float(np.max(np.abs(command))),'maximum_lqr_slew':float(np.max(np.abs(np.diff(command)))),'maximum_runtime_replay_error':float(error),'start_gate_reasons':reasons,'restoration':{k:rows[-1][k] for k in ('restored_roll_override','restored_pitch_override','restored_roll_yoke_error','restored_pitch_yoke_error')},'checks':checks,'pass':all(checks.values())};print(json.dumps(result,indent=2));raise SystemExit(0 if result['pass'] else 1)

if __name__=='__main__':main()
